"""Exact original H26 PyTorch checkpoint bytes, zlib+base64 packaged for Git custody.

Source: original H26 2026-11-18 handoff, SHA-256 values frozen in
PR #253 preregistration comment 6980705287. Decompression must match those hashes.
Not retrained or altered; only reversible lossless encoding for source control.
"""
import base64, hashlib, zlib

RECORDS = {
26011639: (
"55427ff362e971603414ff2883cfe203a99fa5fe739c531042cff4477c6a8bd6",
""""""
),
26011640: (
"dbc83bad61db889966bf233276dab6f817aa71ed316b19173384ff5cf7e8aff7",
""""""
),
26011641: (
"d8b4c691cb3e490907036d8f9225f315102aee114e0270d60b262fdcc64338ad",
""""""
),
}

def checkpoint_bytes(seed):
    expected, encoded = RECORDS[int(seed)]
    data = zlib.decompress(base64.b64decode(encoded, validate=True))
    if hashlib.sha256(data).hexdigest() != expected or len(data) != 4029:
        raise AssertionError(f"H26 original checkpoint identity failed for {seed}")
    return data
